      s: { size: 'Tamaño', pMal: 'Probabilidad de malignidad', pM: 'Probabilidad de metástasis' },
      g: { wall: 'Grosor de la pared', septa: 'Tabiques', enh: 'Realce con contraste' },
      st: { ct: 'TC con contraste: pared, tabiques, calcio y realce.', simple: 'Quiste simple: benigno.', minimal: 'Cambios mínimos: benigno.', followup: 'Hallazgos intermedios: seguimiento.', enhancing: 'Tabiques o nódulos que realzan: sospecha de malignidad.', surgery: 'Extirpación quirúrgica.', noBiopsy: 'No biopsiar una masa quística.' },
      ev: { surgery: 'Nefrectomía parcial.', overtreatment: 'Parte de estas lesiones resultarán benignas en la pieza.', followUp: (v) => `Control de imagen n.º ${v.n}.`, discharge: 'Alta: no precisa seguimiento.', pM5: 'Probabilidad de metástasis > 5 %.' },
      dec: { benign: 'Benigno: sin seguimiento.', followUp: 'IIF: imagen a los 6 y 12 meses y luego anual.', surgery: 'III–IV: cirugía conservadora si es posible.' },
